        // One stake on a free cell touching the piece. No free cell: the piece stands unstaked rather than crowding anything.
        private void PlantStake(RM_FloodlineClaim claim)
        {
            if (claim.stake != null)
            {
                return;
            }
            foreach (IntVec3 c in GenAdj.CardinalAndDiagonalAdjacentCells(claim.cell))
            {
                if (GoodGround(c, map) && c.GetEdifice(map) == null && c.GetFirstItem(map) == null)
